const rolesListRolesForPlugins = `-- name: RolesListRolesForPlugins :many
SELECT r.role_urn::text AS role_urn, r.name::text AS name,
       trim(BOTH '-' FROM regexp_replace(
         lower(regexp_replace(r.name, E'[^a-zA-Z0-9 \t\n\f\r-]', '', 'g')),
         E'[- \t\n\f\r]+', '-', 'g'))::text AS slug
FROM (
  SELECT 'role:organization:' || id AS role_urn, workos_name AS name
  FROM organization_roles WHERE organization_id = $1 AND deleted IS FALSE AND workos_deleted IS FALSE
  UNION ALL
  SELECT 'role:global:' || id, workos_name
  FROM global_roles WHERE deleted IS FALSE AND workos_deleted IS FALSE
) r
`

type RolesListRolesForPluginsRow struct {
	RoleUrn string
	Name    string
	Slug    string
}

// Every role (the tenant's custom ones, then the global ones) with the plugin
// slug it maps to. The slug matches conv.ToSlug, including Go's ASCII-only
// whitespace class.
func (q *Queries) RolesListRolesForPlugins(ctx context.Context, organizationID string) ([]RolesListRolesForPluginsRow, error) {
	rows, err := q.db.Query(ctx, rolesListRolesForPlugins, organizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RolesListRolesForPluginsRow
	for rows.Next() {
		var i RolesListRolesForPluginsRow
		if err := rows.Scan(&i.RoleUrn, &i.Name, &i.Slug); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

