const rolesSetReadOnlyDisposition = `-- name: RolesSetReadOnlyDisposition :exec
UPDATE principal_grants
SET selectors = selectors || jsonb_build_object('disposition', 'read_only')
WHERE principal_grants.organization_id = $1::text
  AND scope = 'mcp:connect'
  AND principal_urn = (
    SELECT 'role:organization:' || r.id FROM organization_roles r
    WHERE r.organization_id = $1::text AND r.workos_slug = 'read-only-tools')
`

